css:
.qb-quote { font-family: Georgia, serif; background: #ffffff; color: #222; padding: 32px 24px; margin: 12px 0; text-align: center; }
.qb-quote-text { font-size: 1.25em; line-height: 1.6; white-space: pre-wrap; }
.qb-author { font-style: italic; color: #666; margin-top: 12px; }
.qb-site-header { display: flex; justify-content: space-between; font-size: 0.75em; color: #999; margin-bottom: 8px; text-align: left; }
.qb-rating { margin-top: 8px; color: #b8960c; }
.qb-meta { margin-top: 6px; font-size: 0.8em; color: #999; }
.qb-source-url { margin-top: 8px; font-size: 0.8em; }
.qb-source-url a { color: #666; }
.qb-branding { margin-top: 10px; font-size: 0.75em; color: #bbb; text-align: center; }
